#!/usr/bin/env python3
"""Measures how a worker uses the test names of the FACTS entries it saw.

Usage: analyze.py OUT.json TRANSCRIPT.jsonl ...
For each transcript it writes one record: the entries seen (with the way),
the test names they hold, the later uses of each name, the Detail reports
read, and every test run with the source of each test name it runs.
"""
import json, re, sys, os

UNI = set(open('/home/user/fortress/tmp/test-names-use/universe.txt').read().split())
STOP = {'README', 'Makefile', 'OneLibraryComponents'}
UNI -= STOP
TESTDIR = re.compile(r'(?:ProjectFortress/)?(?:tests|compiler_tests|library_tests|linker_tests|one_library_tests|other_compiler_tests|parser_tests|shelltests|syntax_abstraction_tests|not_working_\w+|obsolete_interpreter_tests)/([A-Za-z][A-Za-z0-9_]+)')
TESTISH = re.compile(r'^(XXX\w+|\w+(Walk|Compiled|Checker|JUTest|Test|Linked|Rung[A-Z]\w*)\d*)$')
ENTRY = re.compile(r'(F-\d+) \*\*([^\n]*)')
GATE = re.compile(r'(Gated by|Tests?:|Guarded by|Gate:|Checked by|Held by the test)')
BT = re.compile(r'`([^`]+)`')
WORD = lambda n: re.compile(r'(?<![A-Za-z0-9_])' + re.escape(n) + r'(?![A-Za-z0-9_])')

def norm_tokens(tok):
    out = []
    for t in re.split(r'[\s,;()]+', tok):
        t = t.strip().rstrip('.')
        if not t:
            continue
        b = t.split('/')[-1]
        glob = b.endswith('*')
        b = b.rstrip('*')
        b = re.sub(r'\.(fss|fsi|test|java|tfs)$', '', b)
        if not re.match(r'^[A-Za-z][A-Za-z0-9_]{3,}$', b):
            continue
        if glob:
            out += [u for u in UNI if u.startswith(b)]
        else:
            out.append(b)
    return out

def entry_tests(text):
    """Test names of an entry: (names of its test sentence, other test names)."""
    gate, other = set(), set()
    m = GATE.search(text)
    gtext = ''
    if m:
        end = text.find('Detail:', m.start())
        gtext = text[m.start(): end if end > 0 else len(text)]
        for tok in BT.findall(gtext):
            for b in norm_tokens(tok):
                if b in UNI or TESTISH.match(b):
                    gate.add(b)
    rest = text.replace(gtext, '')
    for tok in BT.findall(rest):
        has_dir = bool(TESTDIR.search(tok))
        for b in norm_tokens(tok):
            if b in gate:
                continue
            if (b in UNI and (has_dir or TESTISH.match(b))):
                other.add(b)
    return gate, other

def detail_paths(text):
    i = text.find('Detail:')
    if i < 0:
        return []
    ps = []
    for tok in BT.findall(text[i:]):
        if '/' in tok or tok.endswith('.md'):
            ps.append(tok.split('#')[0].split(' ')[0])
    return ps

def content_text(c):
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        out = []
        for b in c:
            if isinstance(b, dict):
                if b.get('type') == 'text':
                    out.append(b.get('text', ''))
                elif b.get('type') == 'tool_result':
                    out.append(content_text(b.get('content')))
        return '\n'.join(out)
    return ''

RUN = re.compile(r'harness-one\.sh|junit\.sh|fortress junit|\bant\b[^\n|;&]*-D\w*test|bin/fortress\s+(walk|compile|run|typecheck|junit)\b|bin/fortress\s+[^\s-][^\s]*\.fss')
EDITCMD = re.compile(r'sed -i|perl -pi|git mv|> *\S*(tests|_tests)/|cat > |tee |open\([^)]*[\'"]w|write_text|\.write\(|git apply|patch -p')
GREPCMD = re.compile(r'\bgrep\b|\brg\b|\bfind\b|\bls\b|git grep|git log|git show')
OPENCMD = re.compile(r'\bcat\b|\bhead\b|\btail\b|sed -n|\bless\b|\bnl\b|\bawk\b')

def classify_use(tool, inp):
    s = json.dumps(inp)
    if tool in ('Edit', 'Write', 'NotebookEdit', 'MultiEdit'):
        return 'edit'
    if tool == 'Read':
        return 'open'
    if tool in ('Grep', 'Glob'):
        return 'grep'
    if tool == 'Bash':
        c = inp.get('command', '')
        if RUN.search(c):
            return 'run'
        if EDITCMD.search(c):
            return 'edit'
        if GREPCMD.search(c):
            return 'grep'
        if OPENCMD.search(c):
            return 'open'
        return 'bash-other'
    if tool in ('StructuredOutput', 'SubagentHandback'):
        return 'report'
    return 'other:' + tool

def way_of(tool, inp):
    s = json.dumps(inp)
    if tool == 'Bash':
        c = inp.get('command', '')
        if 'facts-extract' in c or re.search(r"\$T\b", c):
            return 'extract'
        if 'FACTS.md' in c:
            return 'read/grep'
        return 'other'
    if tool in ('Read', 'Grep') and 'FACTS.md' in s:
        return 'read/grep'
    if tool == 'Skill':
        return 'skill'
    return 'other'

def result_source(tool, inp, text, name):
    """Source class of a name's appearance in one tool result."""
    w = WORD(name)
    lines = [l for l in text.split('\n') if w.search(l)]
    if any(ENTRY.search(l) for l in lines):
        return 'entry'
    if any(re.match(r'\s*(\d+\t)?\|\s*\d+\s*\|', l) for l in lines):
        return 'ledger'
    c = inp.get('command', '') if tool == 'Bash' else json.dumps(inp)
    if tool == 'Skill':
        return 'skill'
    if 'ledger' in c and 'facts-extract' in c and 'doc:' not in c:
        return 'ledger'
    if 'fortress-gap-ledger' in c:
        return 'ledger'
    if re.search(r"doc:|map:", c) or (tool == 'Read' and re.search(r'explorations/.*\.(md|tex|txt)', c)) or re.search(r'(cat|sed -n|head)[^|]*explorations/\S*\.md', c):
        return 'report'
    if tool in ('Grep', 'Glob') or (tool == 'Bash' and GREPCMD.search(c)):
        if re.search(r'git (log|show|diff)', c):
            return 'git'
        return 'search'
    if tool == 'Bash' and re.search(r'git (log|show|diff)', c):
        return 'git'
    if tool == 'Bash' and RUN.search(c):
        return 'run-output'
    if tool == 'Read':
        return 'file-read'
    return 'other'

def run_names(cmd):
    names = set()
    for m in TESTDIR.finditer(cmd):
        b = re.sub(r'\.(fss|test|fsi)$', '', m.group(1))
        names.add(b)
    for t in re.findall(r'[A-Za-z][A-Za-z0-9_]{3,}', cmd):
        if t in UNI:
            names.add(t)
    names -= STOP
    return names

def analyze(path):
    rows = [json.loads(l) for l in open(path) if l.strip()]
    events = []  # (idx, kind, tool, inp, text, ts, id)
    pending = {}
    first_user = True
    for i, d in enumerate(rows):
        m = d.get('message') or {}
        ts = d.get('timestamp', '')
        c = m.get('content')
        if d.get('type') == 'user':
            if isinstance(c, str) or (isinstance(c, list) and any(b.get('type') == 'text' for b in c if isinstance(b, dict)) and not any(b.get('type') == 'tool_result' for b in c if isinstance(b, dict))):
                events.append((i, 'brief', None, {}, content_text(c), ts))
            elif isinstance(c, list):
                for b in c:
                    if isinstance(b, dict) and b.get('type') == 'tool_result':
                        tu = pending.get(b.get('tool_use_id'), ('?', {}))
                        events.append((i, 'result', tu[0], tu[1], content_text(b.get('content')), ts))
        elif d.get('type') == 'assistant' and isinstance(c, list):
            for b in c:
                if b.get('type') == 'tool_use':
                    pending[b['id']] = (b['name'], b.get('input') or {})
                    events.append((i, 'use', b['name'], b.get('input') or {}, '', ts))
                elif b.get('type') == 'text' and b.get('text', '').strip():
                    events.append((i, 'say', None, {}, b['text'], ts))
    # final report: StructuredOutput/SubagentHandback input, else last assistant text
    rep_idx = None
    for k, e in enumerate(events):
        if e[1] == 'use' and e[2] in ('StructuredOutput', 'SubagentHandback'):
            rep_idx = k
    if rep_idx is None:
        for k, e in enumerate(events):
            if e[1] == 'say':
                rep_idx = k
    # entries seen
    seen = {}  # F-n -> dict(first event k, way, text, gate, other, details)
    brief_named = set()
    for k, e in enumerate(events):
        if e[1] == 'brief':
            for f in re.findall(r'\bF-(\d+)\b', e[4]):
                brief_named.add('F-' + f)
        if e[1] in ('brief', 'result'):
            way = 'brief' if e[1] == 'brief' else way_of(e[2], e[3])
            for m in ENTRY.finditer(e[4]):
                f, text = m.group(1), m.group(2)
                g, o = entry_tests(text)
                if f not in seen:
                    seen[f] = dict(k=k, line=e[0], ts=e[5], way=way, ways={way}, gate=set(g), other=set(o), details=set(detail_paths(text)))
                else:
                    s = seen[f]; s['ways'].add(way); s['gate'] |= g; s['other'] |= o
                    s['details'] |= set(detail_paths(text))
    # name -> first k it was seen through an entry
    name_seen = {}
    for f, s in seen.items():
        for n in s['gate'] | s['other']:
            # first time this name was visible in this entry: the first event that printed the entry with the name
            for k, e in enumerate(events):
                if e[1] in ('brief', 'result') and k >= s['k'] and any(WORD(n).search(m.group(0)) for m in ENTRY.finditer(e[4]) if m.group(1) == f):
                    if n not in name_seen or k < name_seen[n][0]:
                        name_seen[n] = (k, f, 'gate' if n in s['gate'] else 'other')
                    break
    brief_text = '\n'.join(e[4] for e in events if e[1] == 'brief')
    brief_nonentry = re.sub(r'F-\d+ \*\*[^\n]*', '', brief_text)
    uses = {}
    for n, (k0, f, where) in name_seen.items():
        w = WORD(n)
        u = []
        for k in range(k0 + 1, len(events)):
            e = events[k]
            if e[1] != 'use':
                continue
            if w.search(json.dumps(e[3])):
                kind = 'report' if k == rep_idx else classify_use(e[2], e[3])
                u.append(dict(kind=kind, line=e[0], ts=e[5], tool=e[2], cmd=(e[3].get('command') or e[3].get('file_path') or e[3].get('pattern') or '')[:300]))
        if rep_idx is not None and events[rep_idx][1] == 'say' and rep_idx > k0 and w.search(events[rep_idx][4]):
            u.append(dict(kind='report', line=events[rep_idx][0], ts=events[rep_idx][5], tool='text', cmd=''))
        uses[n] = dict(entry=f, where=where, seen_line=events[k0][0], seen_ts=events[k0][5],
                       in_brief_outside_entry=bool(w.search(brief_nonentry)), uses=u)
    # details read
    details = []
    for f, s in seen.items():
        for p in s['details']:
            tail = p.lstrip('./')
            hit = None
            for k in range(s['k'] + 1, len(events)):
                e = events[k]
                if e[1] == 'use' and tail in json.dumps(e[3]):
                    hit = k
                    break
            rep_only = []
            if hit is not None:
                res = ''
                for k2 in range(hit + 1, min(hit + 3, len(events))):
                    if events[k2][1] == 'result':
                        res = events[k2][4]; break
                names = set()
                for t in re.findall(r'[A-Za-z][A-Za-z0-9_]{3,}', res):
                    if t in UNI and TESTISH.match(t):
                        names.add(t)
                names -= (s['gate'] | s['other'])
                names = {n for n in names if not WORD(n).search(brief_text)}
                for n in sorted(names):
                    w = WORD(n)
                    for k3 in range(hit + 2, len(events)):
                        e = events[k3]
                        if e[1] == 'use' and w.search(json.dumps(e[3])):
                            rep_only.append(dict(name=n, kind=classify_use(e[2], e[3]), line=e[0], cmd=(e[3].get('command') or e[3].get('file_path') or '')[:200]))
                            break
                rep_only = [dict(r, report_names=len(names)) for r in rep_only] or [dict(report_names=len(names))]
            details.append(dict(entry=f, path=p, read=hit is not None,
                                read_line=events[hit][0] if hit is not None else None,
                                read_cmd=(json.dumps(events[hit][3])[:200] if hit is not None else None),
                                report_only_uses=rep_only))
    # test runs and their sources
    runs = []
    for k, e in enumerate(events):
        if e[1] == 'use' and e[2] == 'Bash' and RUN.search(e[3].get('command', '')):
            cmd = e[3]['command']
            for n in sorted(run_names(cmd)):
                w = WORD(n)
                src = None
                for k2 in range(0, k + 1):
                    e2 = events[k2]
                    if e2[1] == 'brief' and w.search(e2[4]):
                        lines = [l for l in e2[4].split('\n') if w.search(l)]
                        src = 'entry(brief)' if any(ENTRY.search(l) for l in lines) else 'brief'
                    elif e2[1] == 'result' and w.search(e2[4]):
                        src = result_source(e2[2], e2[3], e2[4], n)
                    elif e2[1] == 'use' and w.search(json.dumps(e2[3])):
                        if e2[2] in ('Write', 'Edit') or (e2[2] == 'Bash' and EDITCMD.search(e2[3].get('command', ''))):
                            src = 'worker wrote it'
                        elif k2 == k:
                            src = 'worker typed it first (in this run)'
                        else:
                            src = 'worker typed it first'
                    if src:
                        srcline = e2[0]
                        break
                runs.append(dict(name=n, line=e[0], ts=e[5], src=src, src_line=srcline,
                                 entry_seen_before=(n in name_seen and name_seen[n][0] < k),
                                 cmd=cmd[:300]))
    # searches for names an entry already gave
    searches = []
    for n, (k0, f, where) in name_seen.items():
        pass
    # changed the tree?
    changed = False
    for e in events:
        if e[1] != 'use':
            continue
        s = json.dumps(e[3])
        if e[2] in ('Edit', 'Write', 'MultiEdit', 'NotebookEdit'):
            p = e[3].get('file_path', '')
            if '/tmp/' not in p and 'scratchpad' not in p and not p.startswith('/tmp'):
                changed = True
        if e[2] == 'Bash' and re.search(r'git (commit|apply|am)\b|git -C \S+ commit', e[3].get('command', '')):
            changed = True
        if e[2] == 'StructuredOutput' and e[3].get('filesChanged'):
            changed = True
    return dict(path=path, n_events=len(events), changed=changed,
                start=events[0][5] if events else '',
                brief_named=sorted(brief_named),
                seen={f: dict(line=s['line'], ts=s['ts'], way=s['way'], ways=sorted(s['ways']), gate=sorted(s['gate']), other=sorted(s['other']), details=sorted(s['details'])) for f, s in seen.items()},
                uses=uses, details=details, runs=runs)

if __name__ == '__main__':
    out = []
    for p in sys.argv[2:]:
        try:
            r = analyze(p)
        except Exception as ex:
            r = dict(path=p, error=repr(ex))
        meta = p[:-6] + '.meta.json'
        if os.path.exists(meta):
            r['meta'] = json.load(open(meta))
        out.append(r)
        print(os.path.basename(p), r.get('changed'), len(r.get('seen', {})), len(r.get('runs', [])), r.get('error', ''), file=sys.stderr)
    json.dump(out, open(sys.argv[1], 'w'), indent=1, default=list)

