    pend = {}
    names = {n: u for n, u in r['uses'].items()}
    hits = {}
    for i, d in enumerate(rows):
        c = (d.get('message') or {}).get('content')
        if not isinstance(c, list): continue
        for b in c:
            if b.get('type') == 'tool_use': pend[b['id']] = (b['name'], b.get('input') or {}, i)
